      "location": "May 09 bar",
      "fact": "The blue Station X segment is visibly thicker than the May 06 blue segment, extending from the 1,500 baseline to roughly the 1,750–1,800 level."
    },
    {
      "location": "May 08 and May 07 bars",
      "fact": "No visible blue Station X segment appears at the base; the green Station Y segment starts at the 1,500 baseline."
    },
    {
      "location": "right side",
      "fact": "Legend swatches are ordered blue = Station X, green = Station Y, orange = Station Z."
    }
  ],
  "printed_facts": [
    {
      "location": "chart title",
      "fact": "“Visitors at Three Train Stations in City Z”"
    },
    {
      "location": "y-axis",
      "fact": "Axis label “Number of Visitors”; ticks printed at 1,500, 2,000, 2,500, 3,000, 3,500, 4,000, 4,500, 5,000."
    },
    {
      "location": "x-axis",
      "fact": "Axis label “Date”; category labels “May 09”, “May 08”, “May 06”, “May 07”."
    },
    {
      "location": "legend",
      "fact": "“Station X” (blue), “Station Y” (green), “Station Z” (orange)."
    },
    {
      "location": "form context",
      "fact": "Review target is “Station X on May 06”; operations program is “Demand status routing”."
    }
  ],
  "public_definitions": [
    "Choose the May 06 Station X demand route from: “Keep May 06 on normal Station X demand monitoring”, “Route May 06 to low-demand response”, or “Route May 06 to high-demand crowding response”.",
    "The transit dashboard is the evidence source for the May 06 Station X routing decision."
  ],
  "uncertain": [
    "No printed threshold defines what visitor count qualifies as normal, low-demand, or high-demand crowding."
    , "The exact numeric value of the May 06 Station X segment is not printed; it must be read from the stacked-bar height."
    , "No policy table is provided to map a specific visitor count to a routing option."
  ]
